class.description:
States are plain integers, so a GDScript enum works as the tile set directly. Declare which states may touch, then call [method generate]. [codeblock] enum Tile { WATER, SAND, GRASS }
var wfc := WaveFunctionCollapse.new() wfc.allow_all(Tile.WATER, Tile.WATER) wfc.allow_all(Tile.WATER, Tile.SAND) wfc.allow_all(Tile.SAND, Tile.SAND) wfc.allow_all(Tile.SAND, Tile.GRASS) wfc.allow_all(Tile.GRASS, Tile.GRASS) wfc.set_weight(Tile.WATER, 1.5)
var grid := wfc.generate(Vector2i(32, 32), 1234) [/codeblock]
